@push('scripts')<script>const token='{{ $table->qr_token }}';const cart=[];function add(id,name){const x=cart.find(i=>i.product_id===id);if(x)x.quantity++;else cart.push({product_id:id,quantity:1,options:[]});render()}function render(){cartEl=document.getElementById('cart');cartEl.innerHTML=cart.length?cart.map(x=>`${x.quantity} × ${x.product_id}`).join('<br>'):'No items yet.';place.disabled=!cart.length;}place.onclick=async()=>{try{const r=await fetch('/api/v1/dine-in/orders',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({table_token:token,items:cart})});const d=await r.json();if(!r.ok)throw Error(d.message||'Please sign in to place this order.');msg.textContent='Order '+d.order_number+' created.';cart.length=0;render();}catch(e){msg.textContent=e.message;msg.className='small mt-2 text-danger';}};</script>@endpush
